import os, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from common import Bank
B = Bank('127.', 1172, own='cte_95.jsonl')
def H(code, d, q, right, wrong, e): return B.hand(code, d, q, right, wrong, e)

# ---- 748 Firefighter I ----
H("748.d.1.A",3,"A fire company officer gives clear spoken orders at a scene and writes a short log afterward. This demonstrates:","speech and written communication platforms common to fire management",["silence","graffiti","guesswork"],"Fire management relies on spoken and written communication.")
H("748.d.1.A",4,"Why do fire departments require written incident logs?","They record what happened for review, training and legal needs",["They decorate the station","They replace radios","They are never read"],"Logs document actions and decisions.")
H("748.d.1.B",3,"A firefighter keys the radio, states the unit name, then gives a short clear message and waits for acknowledgment. This is:","the steps for using radio communication in fire management",["random chatter","avoiding contact","shouting"],"Radio use follows a set format.")
H("748.d.1.B",4,"Which radio habit helps messages be understood at a loud fire scene?","Speak slowly and clearly using plain language",["Mumble quickly","Use private slang","Whisper"],"Clarity prevents errors.")
H("748.d.1.C",3,"At a large fire, one officer is in charge and divides tasks among sections such as operations and logistics. This is the:","Incident Command System",["Fire triangle","Hose lay","Air bottle"],"ICS organizes emergency response.")
H("748.d.1.C",4,"The main benefit of using the Incident Command System is that it:","gives a clear chain of command and organized roles",["removes all risk","eliminates radios","ends training"],"ICS prevents confusion.")
H("748.d.1.D",3,"Firefighters arrive at a highway crash, place warning devices and protect the scene from traffic before helping the injured. This is applying:","protocols for working at an accident scene",["ignoring danger","leaving the area","blocking help"],"Scene protection comes first.")
H("748.d.1.D",4,"The first step at a vehicle accident scene is generally to:","size up the scene and make it safe",["move every car","skip safety","start paperwork"],"Safety first.")
H("748.d.2.A",3,"A station follows OSHA rules and the NFPA standards about protective gear. These are:","local, state and federal regulations on safety",["suggestions","menu rules","parking tips"],"Regulations set safety requirements.")
H("748.d.2.A",4,"Why must a fire department follow federal and state safety regulations?","They reduce injuries and are legally required",["They are optional","They look good","They save paper only"],"Compliance protects firefighters.")
H("748.d.2.B",3,"A first-arriving crew sees a tanker leaking an unknown liquid, stays back and calls for a hazmat team. This is:","awareness-level protocol for hazardous materials",["entering the spill","ignoring the leak","touching the liquid"],"Awareness-level responders identify and isolate, not clean up.")
H("748.d.2.B",4,"At the awareness level, firefighters are trained to:","recognize a hazardous material, isolate the area and call for help",["neutralize the chemical","enter the leak","collect samples"],"They protect the public and notify specialists.")
H("748.d.2.C",3,"Before a drill, a firefighter checks gear, hydrates and follows lifting rules. These are:","personal safety procedures",["optional steps","wasted time","extra work"],"Personal safety prevents injury.")
H("748.d.2.C",4,"Which personal safety practice reduces back injuries on the fireground?","Using proper lifting technique and team lifts",["Lifting alone with a twist","Skipping stretching","Carrying heavy gear one-handed"],"Technique protects the body.")
H("748.d.3.A",3,"A new recruit learns to listen, follow instructions and share tasks with her crew. This is:","functioning within a group environment",["working alone","quitting","avoiding feedback"],"Teamwork is essential in firefighting.")
H("748.d.3.A",4,"Which behavior best supports teamwork on a fire crew?","Communicating clearly and supporting crew members",["Ignoring orders","Competing for credit","Working separately"],"Cooperation improves safety.")
H("748.d.3.B",3,"A senior firefighter stays calm, sets an example in following safety rules and mentors a rookie. This demonstrates:","model leadership in fire management",["poor leadership","showing off","avoidance"],"Leaders lead by example.")
H("748.d.3.B",4,"A strong fire service leader shows leadership by:","acting with integrity and setting a good example",["breaking rules","ignoring crew","avoiding training"],"Integrity builds trust.")
H("748.d.4.A",3,"A recruit looks up the Texas rules that govern basic firefighter certification. This is identifying:","the laws and rules for basic firefighter certification",["school rules","parking rules","menu rules"],"Certification follows state rules.")
H("748.d.4.A",4,"Which agency's rules apply to firefighter certification in Texas?","Texas Commission on Fire Protection",["State library","Highway department","Parks department"],"TCFP certifies Texas firefighters.")
H("748.d.4.B",3,"A trainee reads about the training hours and exams needed to become a certified firefighter. This is:","reviewing Texas Commission on Fire Protection certification requirements",["avoiding rules","ignoring exams","skipping training"],"Requirements include training and testing.")
H("748.d.4.B",4,"To become a certified Texas firefighter, a person must typically:","complete approved training and pass the required exams",["only apply","only pay a fee","only watch videos"],"Training and testing are required.")
H("748.d.4.C",3,"Basic, intermediate, advanced and master are examples of:","firefighter certification levels",["school grades","truck models","hose sizes"],"Certification has levels.")
H("748.d.4.C",4,"A higher firefighter certification level generally requires:","more training, experience and education",["less training","no experience","no testing"],"Higher levels demand more.")
H("748.d.4.D",3,"A firefighter earns a certificate to teach new recruits. This relates to:","levels of instructor certification",["hose coupling","engine pumping","radio frequency"],"Instructors have their own levels.")
H("748.d.4.D",4,"A person who wishes to teach at a fire academy must usually:","hold instructor certification from the state",["avoid training","have no experience","be a visitor"],"Instructors must be certified.")
H("748.d.4.E",3,"The NFPA sets standards for firefighter duties. A recruit who learns what she must be able to do on the job is studying:","a firefighter's responsibilities per NFPA standards",["menu planning","fashion","sports"],"NFPA 1001 sets job performance requirements.")
H("748.d.4.E",4,"The NFPA is best known for developing:","fire and life safety codes and standards",["road maps","tax rules","recipes"],"NFPA publishes safety standards.")
H("748.d.5.A",3,"In a structure fire, smoke, heat and toxic gases are the products of combustion that can harm firefighters. These include:","gases, flame, heat and smoke",["only water","only wind","only light"],"Four products of combustion are gases, flame, heat and smoke.")
H("748.d.5.A",4,"Which is a dangerous product of combustion in a structure fire?","carbon monoxide gas",["fresh air","water vapor only","dust only"],"CO is a deadly gas.")
H("748.d.5.B",3,"The lowest temperature at which a liquid gives off enough vapor to ignite is its:","flash point",["freezing point","boiling point only","melting point"],"Flash point is a basic fire term.")
H("748.d.5.B",4,"Ignition temperature is the minimum temperature at which a substance will:","ignite and continue to burn without an outside flame",["melt","freeze","evaporate"],"Self-sustained ignition.")
H("748.d.5.C",3,"In a room fire, the hottest gases collect near the ceiling while cooler air stays near the floor. This is called:","thermal layering",["backdraft","a hose lay","flame spread only"],"Hot gases rise and form layers.")
H("748.d.5.C",4,"Why do firefighters stay low when moving through a smoky room?","Thermal layering puts the hottest gases high and cooler, clearer air low",["Gravity is stronger low","Smoke sinks to the floor","It is faster to crawl"],"Cooler air lies near the floor.")
H("748.d.5.D",3,"Oxygen, heat, fuel and a chemical chain reaction are the parts of the:","fire tetrahedron",["wind square","hose triangle","ladder cube"],"The tetrahedron adds the chain reaction.")
H("748.d.5.D",4,"Removing which part of the fire triangle will stop a fire?","fuel, oxygen or heat",["only the color","only the sound","only the smell"],"Remove one side.")
H("748.d.5.E",3,"A short in a wire that starts a fire is an example of an:","electrical heat energy source",["nuclear source","mechanical source only","chemical source only"],"Electrical energy can ignite materials.")
H("748.d.5.E",4,"Friction from two surfaces rubbing together producing heat is a:","mechanical heat energy source",["nuclear source","chemical source","solar source"],"Friction creates heat.")
H("748.d.5.F",3,"From incipient to growth, fully developed and decay, a fire passes through:","stages of fire development",["school grades","moon phases","traffic lights"],"Fire progresses through stages.")
H("748.d.5.F",4,"The stage of fire when it is just starting and still small is the:","incipient stage",["decay stage","fully developed stage","flashover"],"Incipient = beginning.")
H("748.d.5.G",3,"A sudden event in which all contents of a room ignite at once is called:","flashover",["backdraft","a thermal layer","hydrant"],"Flashover is a rapid transition.")
H("748.d.5.G",4,"When oxygen is suddenly introduced to an oxygen-starved fire and causes an explosion, it is called a:","backdraft",["flashover","rollover","draft"],"Backdraft is a violent explosion.")
H("748.d.5.H",3,"A British thermal unit and a calorie are both units of:","heat measurement",["distance","speed","weight"],"Both measure heat energy.")
H("748.d.5.H",4,"Converting between Fahrenheit and Celsius is an example of:","converting units of temperature measurement",["measuring distance","measuring weight","measuring time"],"Unit conversion is part of fire science.")
H("748.d.6.A",3,"Heat moving through a metal pipe from a fire to a wall is:","conduction",["radiation","convection","condensation"],"Conduction transfers heat by contact.")
H("748.d.6.A",4,"Heat carried by rising hot gases is called:","convection",["conduction","radiation","insulation"],"Convection moves heat through fluids.")
H("748.d.6.B",3,"A firefighter feels heat across a street from a burning building without touching it. This is an example of heat transfer by:","radiation",["conduction","convection","absorption"],"Radiation travels as waves.")
H("748.d.6.B",4,"A fire spreading to a neighboring house by heat waves across a gap is an example of:","radiant heat transfer",["conduction through air","convection through wood","water transfer"],"Radiant heat can ignite nearby structures.")
H("748.d.7.A",3,"Fuels commonly appear as solids, liquids or gases. These are:","the physical states of matter in which fuels are found",["wind types","hose types","truck types"],"Fuel state affects how it burns.")
H("748.d.7.A",4,"Gasoline in a tank is a fuel in which state of matter?","liquid",["solid","plasma","none"],"Gasoline is a liquid fuel.")
H("748.d.7.B",3,"Specific gravity and vapor density help firefighters predict whether a leaked vapor will sink or rise. These are terms related to:","the combustion process",["hose types","truck parts","station design"],"They describe fuel behavior.")
H("748.d.7.B",4,"A vapor with a density greater than air will usually:","sink and collect in low areas",["rise to the ceiling","vanish","freeze"],"Heavier vapors pool low.")
H("748.d.7.C",3,"Carbon monoxide and hydrogen cyanide are dangerous gases found in smoke because they:","poison people and reduce oxygen use by the body",["smell like flowers","cool the room","are harmless"],"They are asphyxiants.")
H("748.d.7.C",4,"An irritant gas in smoke would most likely cause:","burning eyes and coughing",["no effect","faster breathing only","improved vision"],"Irritants affect eyes and airways.")
H("748.d.8.A",3,"Fire extinguishment theory says a fire can be put out by removing one or more parts of the:","fire triangle or tetrahedron",["roof","hydrant","engine"],"Remove heat, fuel, oxygen or the reaction.")
H("748.d.8.A",4,"Which statement fits extinguishment theory?","A fire goes out when one of its essential elements is removed",["Fires always go out on their own","Fires need no fuel","Fires only need heat"],"Remove a side of the triangle.")
H("748.d.8.B",3,"Spraying water on a fire cools it. This is a method of extinguishment called:","temperature reduction",["fuel removal","oxygen exclusion","chain breaking"],"Cooling removes heat.")
H("748.d.8.B",4,"Closing a valve to stop gas flowing to a burning pipe is an example of:","fuel removal",["temperature reduction","oxygen exclusion","chain inhibition"],"Remove the fuel.")
H("748.d.9.A",3,"The amount of heat needed to raise the temperature of a substance is described by its:","specific heat",["pressure","speed","color"],"Specific heat is a thermodynamics concept.")
H("748.d.9.A",4,"Latent heat is the energy that is absorbed or released when a substance changes:","state, such as water to steam",["color","name","weight only"],"Latent heat accompanies phase changes.")
H("748.d.9.B",3,"Water absorbs a great deal of heat and expands when it turns to steam. This is an advantage of water because it:","cools well and is widely available",["is a fuel","burns","removes oxygen only"],"Water cools efficiently.")
H("748.d.9.B",4,"A disadvantage of using water on a fire involving live electrical equipment is that water can:","conduct electricity and create a shock hazard",["help the fire","freeze","vanish"],"Water conducts electricity.")
H("748.d.10.A",3,"The respiratory and circulatory systems supply the body with oxygen. A firefighter studies these because:","breathing apparatus protects these life-sustaining systems",["they are unimportant","they are decorative","they are fire fuel"],"Understanding the body supports safe SCBA use.")
H("748.d.10.A",4,"Which body system carries oxygen from the lungs to the rest of the body?","circulatory system",["digestive system","skeletal system","nervous system only"],"Blood carries oxygen.")
H("748.d.10.B",3,"A department follows national standards for choosing and maintaining breathing apparatus. These are:","NFPA standards for SCBA selection, care and maintenance",["menu standards","parking standards","sports standards"],"NFPA addresses SCBA.")
H("748.d.10.B",4,"Why do departments follow NFPA standards for breathing apparatus?","They help ensure the equipment protects firefighters",["They are decorations","They are never used","They limit training"],"Standards ensure reliability.")
H("748.d.10.C",3,"Before wearing an SCBA, a firefighter must meet medical and fitness requirements. This identifies:","the physical requirements for wearing an SCBA",["no requirements","only uniform rules","only age"],"Wearing SCBA is demanding.")
H("748.d.10.C",4,"Which condition could make wearing an SCBA unsafe for a firefighter?","a serious respiratory or heart problem",["short hair","a loud voice","tall height only"],"Medical clearance is needed.")
H("748.d.10.D",3,"A burning building filled with smoke contains oxygen-poor air and toxic gases. These are:","respiratory hazards that require breathing protection",["harmless gases","pleasant smells","only water vapor"],"Smoke is hazardous to breathe.")
H("748.d.10.D",4,"Which firefighting condition most clearly requires a breathing apparatus?","a smoke-filled environment",["a clear field","a paved road","a sunny day"],"Smoke requires SCBA.")
H("748.d.10.E",3,"An open-circuit SCBA exhales into the air, while a closed-circuit unit recycles air. These are:","different types of self-contained breathing apparatus",["types of hose","types of ladders","types of trucks"],"Open and closed circuit.")
H("748.d.10.E",4,"The most common SCBA used in structural firefighting is the:","open-circuit SCBA",["scuba tank","oxygen mask for pilots","dust mask"],"Open circuit is standard.")
H("748.d.10.F",3,"An open-circuit SCBA has a pressure gauge, an alarm and a regulator. These are:","safety features and functions of the unit",["cosmetic features","unneeded parts","toys"],"Safety features warn the wearer.")
H("748.d.10.F",4,"The low-air alarm on an SCBA warns the firefighter that:","the air supply is running low and it is time to exit",["the fire is out","the battery is full","the wind changed"],"Low-air alarm triggers exit.")
H("748.d.11.A",3,"Before entering a smoky building, a firefighter checks the SCBA gauge, mask seal and alarm. This is following:","safety requirements for using the breathing apparatus",["optional steps","wasted time","guesswork"],"Pre-entry checks prevent failures.")
H("748.d.11.A",4,"A firefighter's SCBA should be inspected for a full cylinder and a working alarm:","before every use",["once a year only","only after a fire","never"],"Check before use.")
H("748.d.11.B",3,"A 30-minute cylinder holds about 1,800 cubic feet of air, and a firefighter breathes 60 cubic feet per minute. Estimating how long the air lasts is:","calculating the air supply duration",["guessing","ignoring the gauge","avoiding math"],"1,800 ÷ 60 = 30 minutes.")
H("748.d.11.B",4,"A cylinder holds 1,200 cubic feet of air and a firefighter uses 40 cubic feet per minute. How long will the air last?","30 minutes",["20 minutes","48 minutes","1,160 minutes"],"1,200 ÷ 40 = 30.")
H("748.d.11.C",3,"One safety rule for wearing an SCBA is to never remove the facepiece while in a contaminated area. The reason is:","toxic smoke can quickly cause serious injury",["it looks bad","it saves air","it is a tradition"],"Facepieces protect the airway.")
H("748.d.11.C",4,"The buddy system when wearing SCBA means that firefighters:","enter, work and leave together",["work alone","split up","avoid radios"],"Buddies watch each other.")
H("748.d.11.D",3,"An SCBA provides clean air but does not protect against heat or cuts. This describes its:","uses and limitations",["only uses","only color","no limits"],"SCBA protects breathing only.")
H("748.d.11.D",4,"A limitation of an SCBA in a long rescue is that:","the air supply in the cylinder is limited",["it never runs out","it cannot be seen","it is weightless"],"Air supply is finite.")
H("748.d.11.E",3,"A firefighter practices putting on the SCBA over her coat and then removing it quickly after an exercise. This demonstrates:","donning and doffing the breathing apparatus",["avoiding training","ignoring gear","breaking gear"],"Donning methods are practiced.")
H("748.d.11.E",4,"When donning an SCBA, the facepiece should be checked for:","a proper seal before entering a hazard area",["bright color","scratches only","a name tag"],"A seal prevents smoke entry.")
H("748.d.11.F",3,"After a low-air alarm, a firefighter trades an empty cylinder for a full one at the rehab area. This is:","replacing an expended cylinder",["adding a hose","changing a boot","cleaning a helmet"],"Cylinder replacement is a skill.")
H("748.d.11.F",4,"When replacing an SCBA cylinder, the firefighter should always:","check that the new cylinder is full and the connection is tight",["skip testing","use any cylinder","ignore leaks"],"Verify the new cylinder.")
H("748.d.11.G",3,"A rescuer with an SCBA must reach an unconscious person without removing her own mask. This demonstrates:","rescue procedures that protect the rescuer's breathing",["unsafe rescue","avoiding rescue","ignoring risk"],"The rescuer must keep their own air.")
H("748.d.11.G",4,"During a rescue in smoke, the firefighter's top priority regarding her own air is to:","keep her facepiece on and monitor her supply",["remove the mask","ignore the gauge","share her mask first"],"Rescuers must not become victims.")
H("748.d.11.H",3,"A firefighter advances a hose line while wearing an SCBA. This is performing:","firefighting skills while wearing the breathing apparatus",["sports","jogging only","sitting"],"Tasks are performed in gear.")
H("748.d.11.H",4,"Compared with working without an SCBA, working with one usually:","adds weight and limits vision and movement",["makes the work lighter","improves hearing","removes risk"],"SCBA adds load and limits mobility.")
H("748.d.11.I",3,"A firefighter crawls through a tight space under a collapsed ceiling and has to use a technique to keep the SCBA from snagging. This is:","using the SCBA in a restricted space",["avoiding tight spaces","removing the gear","using no technique"],"Restricted spaces require special handling.")
H("748.d.11.I",4,"In a restricted opening, a firefighter might slip the SCBA off one shoulder while:","keeping the facepiece on and staying connected to the air",["removing the mask","dropping the cylinder","closing the valve"],"Maintain airway protection.")
H("748.d.11.J",3,"If an SCBA regulator suddenly stops delivering air, a firefighter follows emergency procedures such as bypass and calling a Mayday. This is:","emergency procedures for SCBA failure",["ignoring the problem","removing the mask","waiting"],"Failures require immediate action.")
H("748.d.11.J",4,"If an SCBA fails inside a burning building, the firefighter should first:","activate the bypass, call for help and exit",["panic","hold her breath and stay","take off her coat"],"Use emergency procedures.")
H("748.d.12.A",3,"A firefighter writes down the date a regulator was cleaned and a cylinder was tested. This is:","documenting routine SCBA maintenance",["avoiding records","skipping inspections","hiding errors"],"Records show equipment care.")
H("748.d.12.A",4,"Keeping a log of SCBA maintenance helps a department:","prove equipment was inspected and serviced",["avoid inspections","raise costs","hide damage"],"Records support safety and compliance.")
H("748.d.12.B",3,"A fill station compresses air and recharges SCBA cylinders at the firehouse. This is an:","air supply system for recharging cylinders",["hose washer","ladder rack","radio charger"],"Cascade or compressor systems refill cylinders.")
H("748.d.12.B",4,"The air used to fill SCBA cylinders must be:","clean, dry breathable air tested to standards",["any air","smoky air","moist air"],"Breathing air must meet quality standards.")
H("748.d.13.A",3,"Structural gear, wildland gear and proximity suits are different types of:","fire service protective clothing",["uniforms for parades","street clothes","sports uniforms"],"Different hazards need different gear.")
H("748.d.13.A",4,"Which type of protective clothing is designed to reflect extreme radiant heat near a large fire?","a proximity suit",["a rain jacket","a sweater","a T-shirt"],"Proximity suits reflect heat.")
H("748.d.13.B",3,"A helmet, hood, coat, pants, gloves and boots make up:","structural firefighting protective equipment",["a sports kit","a school uniform","a picnic set"],"The ensemble protects the body.")
H("748.d.13.B",4,"The hood in a structural firefighting ensemble protects:","the neck and ears not covered by the helmet or mask",["the hands","the feet","the knees"],"Hoods cover exposed skin.")
H("748.d.13.C",3,"After a fire, a firefighter looks for burns, tears and worn stitching on her coat and cleans it per procedure. This is:","inspecting and maintaining personal protective equipment",["ignoring gear","tossing gear","painting gear"],"Gear must be inspected and cleaned.")
H("748.d.13.C",4,"Why should damaged PPE be taken out of service?","It may not protect the firefighter properly",["It adds weight","It saves money","It looks old"],"Damaged gear can fail.")
H("748.d.13.D",3,"Structural gear protects against heat for a limited time but cannot make a firefighter immune to extreme conditions. This describes:","limitations of PPE",["PPE perfection","PPE absence","PPE decoration"],"PPE has limits.")
H("748.d.13.D",4,"A limitation of firefighter PPE is that it:","cannot protect indefinitely against intense heat or flames",["is always perfect","stops all injuries","is unbreakable"],"Heat can still penetrate.")
H("748.d.13.E",3,"Wearing heavy gear in a hot building can lead to dehydration and exhaustion. These are:","physical limitations of a firefighter in PPE",["PPE advantages","gear style","gear brands"],"Heat stress is a risk.")
H("748.d.13.E",4,"Which condition is a risk for firefighters working hard in full PPE?","heat exhaustion",["frostbite only","sunburn only","dry mouth only"],"PPE traps body heat.")
H("748.d.13.F",3,"A firefighter practices pulling on boots, coat, hood, helmet and gloves within a time limit. This is:","donning and doffing personal protective equipment",["avoiding gear","slowing the response","dressing for school"],"Speed and correctness matter.")
H("748.d.13.F",4,"A correct donning of PPE leaves:","no skin exposed and all closures fastened",["skin exposed","flaps open","straps loose"],"Full coverage is required.")
H("748.d.14.A",3,"A personal alert safety system, or PASS, sounds an alarm if a firefighter stops moving. This is the proper:","operation of a PASS device",["rescue ladder","siren test","radio check"],"PASS alerts others to a downed firefighter.")
H("748.d.14.A",4,"A PASS device automatically sounds if a firefighter:","remains motionless for a set time",["moves quickly","uses a radio","drinks water"],"Motion sensing triggers the alarm.")
H("748.d.14.B",3,"Before entering a hazard, a firefighter turns on the PASS and checks that the alarm activates. This is:","testing the PASS device",["ignoring safety","skipping checks","removing the device"],"Test before use.")
H("748.d.14.B",4,"When testing a PASS device, the firefighter should confirm:","it activates a loud alarm and resets properly",["it plays music","it is silent","it is hot"],"Function must be verified.")
H("748.d.15.A",3,"A recruit learns that a department has a chief, captains, lieutenants and firefighters. This is the:","organization of a fire department",["layout of a hospital","layout of a school","structure of a bank"],"Departments have a rank structure.")
H("748.d.15.A",4,"The chain of command in a fire department means that:","orders flow from higher ranks to lower ranks",["everyone gives orders","no one gives orders","orders are random"],"Chain of command ensures order.")
H("748.d.15.B",3,"A firefighter understands that each member must do assigned tasks so the crew can succeed. This is her role as a:","member of the fire department",["spectator","outsider","visitor"],"Each member contributes.")
H("748.d.15.B",4,"A firefighter's duty as a team member includes:","following orders and supporting the crew",["acting alone","avoiding training","ignoring others"],"Teamwork supports safety.")
H("748.d.15.C",3,"A department's written rules on uniforms, conduct and attendance are examples of:","rules and regulations common to most fire departments",["suggestions","jokes","rumors"],"Rules set expectations.")
H("748.d.15.C",4,"Why do fire departments enforce rules and regulations?","They promote discipline, safety and consistent performance",["They reduce paperwork","They are optional","They limit teamwork"],"Order depends on rules.")
H("748.d.15.D",3,"Most departments state that their mission is to protect life, property and the environment. This is the:","mission of the fire service",["menu of the station","budget only","hobby list"],"Mission statements guide work.")
H("748.d.15.D",4,"A common mission of a local fire department is to:","protect lives and property through prevention and response",["entertain the public","sell supplies","collect taxes"],"Prevention and response are core.")
H("748.d.15.E",3,"A department's standard operating procedures tell firefighters how to handle common situations the same way. This is the function of a:","standard operating system or procedure",["menu","calendar","logo"],"SOPs give consistent guidance.")
H("748.d.15.E",4,"A benefit of standard operating procedures is that they:","give crews consistent, predictable ways to act",["delay response","confuse crews","remove training"],"Consistency improves safety.")
H("748.d.15.F",3,"A member assistance program offers counseling and support to firefighters dealing with stress. This is a:","component of a member assistance program",["fashion program","food program","sports program"],"These programs support well-being.")
H("748.d.15.F",4,"A member assistance program is meant to help firefighters with:","personal and work-related problems such as stress",["salary raises","uniform choices","engine repair"],"They provide confidential support.")
H("748.d.16.A",3,"At a scene, each firefighter's name and location is tracked on a board so the incident commander knows who is inside. This is a:","personnel accountability system",["menu board","shift schedule","parking lot map"],"Accountability tracks crew locations.")
H("748.d.16.A",4,"The purpose of a personnel accountability system is to:","know where every firefighter is during an incident",["list names alphabetically","track gear costs","assign meals"],"It prevents missing firefighters.")
H("748.d.16.B",3,"Years of exposure to smoke and chemicals can raise a firefighter's risk of certain illnesses. This is a:","long-term health consideration of exposure to products of combustion",["short-term benefit","style choice","sports injury"],"Exposure has long-term effects.")
H("748.d.16.B",4,"Which practice helps reduce long-term health risks from fire exposure?","Cleaning gear and showering after a fire",["Wearing dirty gear","Skipping decontamination","Eating at the scene"],"Decontamination reduces exposure.")
H("748.d.16.C",3,"Slips, strains and burns are common injuries at an emergency scene. These are:","common accidents or injuries in the fire service",["rare events","imaginary","party tricks"],"Injuries often come from falls and strains.")
H("748.d.16.C",4,"A frequent cause of firefighter injury on the fireground is:","overexertion and slips or falls",["too much rest","too little equipment","too many breaks"],"Strain and falls are common.")
H("748.d.16.D",3,"Trapped in a room with no light, a firefighter follows the hose line, activates her PASS and calls a Mayday. This is:","action to take when trapped or disoriented",["panicking","hiding","removing gear"],"Disoriented firefighters follow procedures.")
H("748.d.16.D",4,"If a firefighter becomes lost inside a building, a key first step is to:","call a Mayday and stay calm to conserve air",["run blindly","remove the mask","stop talking"],"Calling a Mayday summons help.")
H("748.d.17.A",3,"Before entering a burning home, a firefighter shuts off the gas and the electric meter. This is:","terminating utility services",["adding power","ignoring risk","starting a fire"],"Utilities are shut off to reduce hazards.")
H("748.d.17.A",4,"Why do firefighters shut off utilities at a structure fire?","Gas and electricity can feed fires and injure crews",["They are decorative","They are free","They are quiet"],"Utility hazards are removed.")
H("748.d.17.B",3,"A downed power line lies across a car. Firefighters should keep back and:","treat all wires as live and call the utility company",["touch the wire","move it with a tool","drive over it"],"Downed lines may be energized.")
H("748.d.17.B",4,"The safe way to approach a scene with fallen electrical wires is to:","stay far away and wait for the utility to de-energize them",["grab them","step across","spray them with water"],"Water can conduct electricity.")
H("748.d.17.C",3,"A firefighter inspects a saw's guard and wears eye protection before cutting. This is:","safe handling and operation of hand and power tools",["unsafe use","ignoring safety","risky shortcuts"],"Safe tool use prevents injuries.")
H("748.d.17.C",4,"Before using a powered rescue tool, a firefighter should:","check it for damage and wear proper protective gear",["skip checks","use it bare-handed","ignore guards"],"Inspection and PPE are required.")
H("748.d.17.D",3,"Portable scene lights run from a generator. A safety step is to keep cords and the generator away from standing water. This is:","safety procedures for fire service lighting equipment",["lighting a stage","avoiding safety","ignoring cords"],"Electrical safety applies to lights.")
H("748.d.17.D",4,"When using a portable generator at an emergency scene, firefighters should:","place it outdoors with ventilation and keep cords out of water",["use it indoors","leave it unattended","use damaged cords"],"Generators produce carbon monoxide.")
H("748.d.17.E",3,"Riding in an engine, a firefighter fastens a seat belt and wears hearing protection when sirens blare. This is using:","safety equipment on apparatus",["no precautions","pranks","optional gear"],"Belts and earplugs protect crews.")
H("748.d.17.E",4,"Why must firefighters wear seat belts while the apparatus is moving?","They prevent ejection and serious injuries in crashes",["They look nice","They slow the truck","They are optional"],"Belts save lives.")
H("748.d.18.A",3,"At a roadway emergency, firefighters wear high-visibility vests and helmets. This is identifying:","protective equipment and its uses",["street fashion","cleaning supplies","office gear"],"Visibility gear protects workers.")
H("748.d.18.A",4,"A high-visibility vest is worn at roadway scenes so that:","drivers can see the firefighters",["the vest keeps them warm","the vest holds tools","the vest looks fancy"],"Visibility reduces strikes.")
H("748.d.18.B",3,"Cones, flares and warning lights placed on a roadway are:","traffic and scene control devices",["decorations","lunch items","tools for cooking"],"They direct and warn traffic.")
H("748.d.18.B",4,"Traffic cones at a crash scene are used to:","redirect traffic away from the work area",["increase speed","block help","mark parking"],"They create a safe zone.")
H("748.d.18.C",3,"Fuel spills, downed lines and unstable vehicles are examples of:","structure fire and roadway emergency scene hazards",["picnic items","decorations","sports gear"],"Scene hazards must be recognized.")
H("748.d.18.C",4,"At a roadway emergency, a major hazard to crews is:","passing traffic",["quiet streets","the weather forecast only","parked cars only"],"Traffic causes many injuries.")
H("748.d.18.D",3,"Parking an engine at an angle to shield the work area is one way to:","mitigate potential scene hazards",["create hazards","ignore traffic","block the street at random"],"Positioning protects crews.")
H("748.d.18.D",4,"A good way to reduce the danger of fuel leaking at a scene is to:","contain the spill and eliminate ignition sources",["add heat","ignore it","spread it"],"Control spill and ignition.")
H("748.d.18.E",3,"A crew uses a spotter, wears protective gear and follows a plan when operating at the scene. These are:","procedures for safe operation at emergency scenes",["unsafe habits","guesses","options"],"Safe operation relies on procedures.")
H("748.d.18.E",4,"A key safe-operation rule at any emergency scene is to:","stay aware of hazards and follow command direction",["work alone","ignore orders","skip PPE"],"Awareness and command maintain safety.")

B.balance()
B.save(os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "batches", "cte_95.jsonl"))
